#!/system/bin/sh
# GENERATED by `cargo makepad android dyn-pack` — shipped as lib/arm64-v8a/libmk-ld.so.
# Link driver for aarch64-linux-android units. rustc infers the plain `ld`
# flavor from the `-ld` name and passes ld-style args; this adds what the
# NDK clang driver would (captured from `clang -###`, proven on the Pixel
# PID1 lane): crt objects, the API sysroot, bionic stubs, builtins, the
# static unwinder, 16 KB page alignment.
D="$MAKEPAD_DYN_DIR"
N="$MAKEPAD_DYN_NLIB"
A="$D/tc/android/lib/@API@"
C="$D/tc/android/lib/clang"
shared=0
for a in "$@"; do
  [ "$a" = "-shared" ] && shared=1
done
if [ "$shared" = 1 ]; then
  b="$A/crtbegin_so.o"
  e="$A/crtend_so.o"
  dl=""
else
  b="$A/crtbegin_dynamic.o"
  e="$A/crtend_android.o"
  dl="--dynamic-linker=/system/bin/linker64"
fi
exec "$N/libld-musl.so" --argv0 ld.lld "$D/tc/lib/rustlib/@RUST_HOST@/bin/rust-lld" -flavor gnu \
  -m aarch64linux --fix-cortex-a53-843419 -z max-page-size=16384 --hash-style=gnu $dl \
  "$b" "$@" \
  -L"$A" -L"$C" \
  -lm -l:libclang_rt.builtins-aarch64-android.a -l:libunwind.a -ldl -lc \
  -l:libclang_rt.builtins-aarch64-android.a -l:libunwind.a -ldl \
  "$e"
